// Get stock data from Details Fetcher (connected upstream)
const stock = $node["Details Fetcher"].json;

// Get AI output (correct key is 'output', not messages[0].content)
const aiOutput = $json.output || 'No AI analysis returned.';

// Build stock summary
const summary =
  `📊 *Stock Summary:*\n` +
  `• Company: ${stock.name} (${stock.symbol})\n` +
  `• Price: $${stock.price}\n` +
  `• Change: $${stock.change} (${parseFloat(stock.changesPercentage).toFixed(2)}%)\n` +
  `• P/E Ratio: ${stock.pe}\n` +
  `• EPS: $${stock.eps}\n` +
  `• Market Cap: $${(stock.marketCap / 1e9).toFixed(2)}B\n` +
  `• Earnings Date: ${new Date(stock.earningsAnnouncement).toDateString()}\n\n`;

// Final message
const message = summary + `🧠 *AI Analysis & Recommendation:*\n` + aiOutput;

return [{ json: { message } }];

